import React from 'react';

interface ModalProps {
  onClose: () => void;
}

const Modal = ({ onClose }: ModalProps) => {
  return <div onClick={() => onClose()}></div>;
};

export default Modal;

import React from 'react';

type StrictButtonProps = { 
  label: string; 
  onClick: () => void; 
};

const Button = (props: StrictButtonProps) => {
  return (
    <button onClick={props.onClick}>
      {props.label}
    </button>
  );
};

const noop = () => {};

const App = () => {
  return (
    <div>
      {/* This will cause a compilation error because 'open' is not part of StrictButtonProps */}
      <Button label="OK" onClick={noop} open={true} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';

interface FakeComponentProps {
  /* no isOpen */
  title: string;
  isOpen: boolean; // Added to satisfy usage and eliminate TS2322
}

const FakeComponent: React.FC<FakeComponentProps> = ({ title, isOpen }) => {
  return <div>{title} — {isOpen ? 'open' : 'closed'}</div>;
};

const App: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div>
      <button onClick={() => setIsOpen(!isOpen)}>
        Toggle
      </button>
      <FakeComponent title="Panel" isOpen={true} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';

const SafeAnimationComponent: React.FC = () => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    setIsVisible(true);
  }, []);

  return (
    <div className="safe-animation-container">
      <div 
        className={`animate-safe ${isVisible ? 'animate-safe--active' : ''}`}
      >
        <p>Animated content</p>
      </div>
    </div>
  );
};

export default SafeAnimationComponent;

import React, { useState, useEffect } from 'react';

const AnimationComponent: React.FC = () => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    setIsVisible(true);
  }, []);

  return (
    <div className="container">
      <div 
        className={`animate-safe ${isVisible ? 'visible' : ''}`}
      >
        Animated Content
      </div>
    </div>
  );
};

export default AnimationComponent;

/* CSS */
.animate-safe {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 300ms cubic-bezier(0.22, 1, 0.36, 1), transform 300ms cubic-bezier(0.22, 1, 0.36, 1);
  animation: example-keyframes 1s ease-in-out;
}

.animate-safe.visible {
  opacity: 1;
  transform: translateY(0);
}

@keyframes example-keyframes {
  from { opacity: 0; }
  to { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .animate-safe {
    animation: none !important;
    transition: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

import React, { useState, useEffect } from 'react';

const useReducedMotion = (): boolean => {
  const [prefersReduced, setPrefersReduced] = useState(false);

  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReduced(mediaQuery.matches);

    const handler = (e: MediaQueryListEvent) => setPrefersReduced(e.matches);
    mediaQuery.addEventListener('change', handler);

    return () => mediaQuery.removeEventListener('change', handler);
  }, []);

  return prefersReduced;
};

const AnimatedBox = () => {
  const shouldReduce = useReducedMotion();

  return (
    <div className={shouldReduce ? '' : 'animate-safe'} />
  );
};

export default AnimatedBox;
